-- users/list
-- One page of accounts for /admin/users, newest first, with each account's last activity (its
-- latest session) and the total for the pager. Shows email to staff only; never exported.
--
-- Parameters, with the example values used to render this file:
--   $1 = 25
--
-- Generated by `pnpm db:queries` from lib/db/queries/users.ts. Do not edit by hand.

select "id", "name", "email", "image", "role", "two_factor_enabled", "banned_at", "ban_reason", "created_at", (select max(s.updated_at)
from sessions s
where s.user_id = "users"."id"), count(*) over ()
from "users"
order by "users"."created_at" desc, "users"."id" desc
limit $1;
